SELECT b.id AS backup_id,b.kind,b.captured_at,b.updated_at,d.key AS day,json_set(json_remove(i.value,'$.fatSecretResults','$.macroEstimateSnapshot.candidateAnnotationsJson'),'$._selectedFood',json_extract(i.value,'$.fatSecretResults[' || (json_extract(i.value,'$.macroEstimateSnapshot.fatSecretIndex')-1) || ']')) AS item_json FROM macro_bundle_backups b,json_each(b.logs_json) d,json_each(d.value) i WHERE b.device_id='alexander' AND d.key BETWEEN '2026-10-12' AND '2026-11-11';